'use strict';
const os = require('node:os');
let reads = 1;
let header = process.report.getReport().header;
const firstHeaderNullish = header == null;
if (firstHeaderNullish) {
  reads++;
  header = process.report.getReport().header;
}
const finalHeaderFalsy = !header;
const glibcVersionRuntime = header && header.glibcVersionRuntime || null;
process.stdout.write(JSON.stringify({
  platform: process.platform, arch: process.arch, nodeVersion: process.version,
  endianness: os.endianness(), execPath: process.execPath, cwd: process.cwd(),
  denoAbsent: typeof process.versions.deno === 'undefined' && typeof globalThis.Deno === 'undefined',
  pnpAbsent: typeof process.versions.pnp === 'undefined',
  requireModule: process.features.require_module === true,
  reportReads: reads, firstHeaderNullish, finalHeaderFalsy, glibcVersionRuntime,
  selectedRollupGnu: finalHeaderFalsy || Boolean(glibcVersionRuntime)
}) + '\n');

